/**
 * check-lint-trend.mjs — Compares current warning count against baseline.
 *
 * Reads .lint-report.json (generated by `poke biome lint --reporter=json`),
 * extracts the warning count, and compares it against a committed baseline
 * in docs/audits/lint-baseline.json.
 *
 * Fails if the count increased.
 *
 * Usage:
 *   poke lint --max-diagnostics=1000 --reporter=json . > .lint-report.json
 *   node scripts/check-lint-trend.mjs
 *
 * To update baseline:
 *   node scripts/check-lint-trend.mjs --update
 */

import { existsSync, readFileSync, writeFileSync } from 'node:fs';

const BASELINE_PATH = 'docs/audits/lint-baseline.json';
const REPORT_PATH = '.lint-report.json';

if (!existsSync(REPORT_PATH)) {
  console.error('No .lint-report.json found. Run poke lint --reporter=json first.');
  process.exit(1);
}

const report = JSON.parse(readFileSync(REPORT_PATH, 'utf8'));
const currentWarnings = report.summary?.warnings ?? 0;

const updateBaseline = process.argv.includes('--update');

if (updateBaseline) {
  const baseline = { warnings: currentWarnings, date: new Date().toISOString().slice(0, 10) };
  writeFileSync(BASELINE_PATH, `${JSON.stringify(baseline, null, 2)}\n`);
  console.log(`Updated baseline to ${currentWarnings} warnings.`);
  process.exit(0);
}

if (!existsSync(BASELINE_PATH)) {
  console.log(`No baseline found at ${BASELINE_PATH}. Creating initial baseline.`);
  writeFileSync(
    BASELINE_PATH,
    `${JSON.stringify(
      { warnings: currentWarnings, date: new Date().toISOString().slice(0, 10) },
      null,
      2,
    )}\n`,
  );
  process.exit(0);
}

const baseline = JSON.parse(readFileSync(BASELINE_PATH, 'utf8'));
const baselineWarnings = baseline.warnings ?? 0;

if (currentWarnings > baselineWarnings) {
  console.error(
    `\u274C Lint warning count increased: ${baselineWarnings} \u2192 ${currentWarnings} ` +
      `(${currentWarnings - baselineWarnings} new warnings).`,
  );
  process.exit(1);
}

console.log(`\u2705 Lint warnings: ${currentWarnings} (baseline: ${baselineWarnings}).`);
process.exit(0);
